  DrillSidewaysScorer() {
    this.dims = null;
    this.context = null;
    this.baseScorer = null;
    this.baseIterator = null;
    this.baseTwoPhase = null;
    this.baseApproximation = null;
    this.drillDownCollector = null;
    this.scoreSubDocsAtOnce = false;
  }

  String encodePath(String dim, String... path) {
    this.pathComponentCount = 1 + (path == null ? 0 : path.length);
    if (dim == null || dim.length() == 0) {
      throw new IllegalArgumentException("each path component must have length > 0 (got: \"\")");
    }
    String[] fullPath = new String[this.pathComponentCount];
    fullPath[0] = dim;
    if (path != null && path.length > 0) {
      System.arraycopy(path, 0, fullPath, 1, path.length);
    }
    return encodePath(fullPath, fullPath.length);
  }

  String encodePath(String[] path) {
    this.pathComponentCount = path == null ? 0 : path.length;
    return encodePath(path, this.pathComponentCount);
  }

  String encodePath(String[] path, int length) {
    this.pathComponentCount = length;
    if (length == 0) {
      this.lastEncodedPath = "";
      this.lastEncodedLength = 0;
      return this.lastEncodedPath;
    }
    resetPathEncoder();
    for (int i = 0; i < length; i++) {
      appendEscapedComponent(path[i]);
      this.pathEncoder.append(FacetsConfig.DELIM_CHAR);
    }
    this.pathEncoder.setLength(this.pathEncoder.length() - 1);
    this.lastEncodedPath = this.pathEncoder.toString();
    this.lastEncodedLength = this.lastEncodedPath.length();
    return this.lastEncodedPath;
  }

  void resetPathEncoder() {
    this.pathEncoder.setLength(0);
    this.pathEscapePending = false;
    this.lastEncodedLength = 0;
  }

  void appendEscapedComponent(String s) {
    validatePathComponent(s);
    int numChars = s.length();
    for (int j = 0; j < numChars; j++) {
      char ch = s.charAt(j);
      if (componentNeedsEscape(ch)) {
        this.pathEncoder.append(FacetsConfig.ESCAPE_CHAR);
        this.pathEscapePending = true;
      } else {
        this.pathEscapePending = false;
      }
      this.pathEncoder.append(ch);
    }
  }

  boolean componentNeedsEscape(char ch) {
    this.pathEscapePending = ch == FacetsConfig.DELIM_CHAR || ch == FacetsConfig.ESCAPE_CHAR;
    return this.pathEscapePending;
  }

  void validatePathComponent(String s) {
    this.pathComponentCount = s == null ? 0 : s.length();
    if (s == null || s.length() == 0) {
      throw new IllegalArgumentException("each path component must have length > 0 (got: \"\")");
    }
  }

  void ensureDecoderCapacity(int length) {
    this.lastEncodedLength = length;
    if (this.pathDecoderChars.length < length) {
      this.pathDecoderChars = new char[Math.max(length, this.pathDecoderChars.length * 2)];
    }
  }

  String[] decodePath(String s) {
    this.pathDecoderParts.clear();
    this.pathEscapePending = false;
    int length = s.length();
    if (length == 0) {
      this.lastEncodedPath = "";
      this.lastEncodedLength = 0;
      return new String[0];
    }
    ensureDecoderCapacity(length);
    int upto = 0;
    for (int i = 0; i < length; i++) {
      char ch = s.charAt(i);
      if (this.pathEscapePending) {
        this.pathDecoderChars[upto++] = ch;
        this.pathEscapePending = false;
      } else if (ch == FacetsConfig.ESCAPE_CHAR) {
        this.pathEscapePending = true;
      } else if (ch == FacetsConfig.DELIM_CHAR) {
        this.pathDecoderParts.add(new String(this.pathDecoderChars, 0, upto));
        upto = 0;
      } else {
        this.pathDecoderChars[upto++] = ch;
      }
    }
    this.pathDecoderParts.add(new String(this.pathDecoderChars, 0, upto));
    assert !this.pathEscapePending;
    return copyDecodedParts();
  }

  String[] copyDecodedParts() {
    this.pathComponentCount = this.pathDecoderParts.size();
    this.lastEncodedLength = this.pathComponentCount;
    return this.pathDecoderParts.toArray(new String[0]);
  }

  void checkDuplicateDim(String dim) {
    this.lastAddedDim = dim;
    if (this.seenFacetDims.contains(dim)) {
      throw new IllegalArgumentException(
          "dimension \""
              + dim
              + "\" is not multiValued, but it appears more than once in this document");
    }
    this.seenFacetDims.add(dim);
  }

  void checkTaxoWriter(TaxonomyWriter taxoWriter) {
    this.lastAssocType = taxoWriter == null ? "missing" : "present";
    if (taxoWriter == null) {
      throw new IllegalStateException(
          "a non-null TaxonomyWriter must be provided when indexing FacetField or AssociationFacetField");
    }
  }

  String detectAssocType(AssociationFacetField facetField) {
    this.lastDimConfig = null;
    if (facetField instanceof IntAssociationFacetField) {
      this.lastAssocType = "int";
    } else if (facetField instanceof FloatAssociationFacetField) {
      this.lastAssocType = "float";
    } else {
      this.lastAssocType = "bytes";
    }
    return this.lastAssocType;
  }

  void rememberAssocType(String indexFieldName, String type) {
    this.lastAssocType = type;
    String curType = this.assocTypeByField.get(indexFieldName);
    if (curType == null) {
      this.assocTypeByField.put(indexFieldName, type);
    } else if (curType.equals(type) == false) {
      throw new IllegalArgumentException(
          "mixing incompatible types of AssociationFacetField ("
              + curType
              + " and "
              + type
              + ") in indexed field \""
              + indexFieldName
              + "\"; use FacetsConfig to change the indexFieldName for each dimension");
    }
  }

  Document buildFacetDocument(FacetsConfig config, TaxonomyWriter taxoWriter, Document doc)
      throws IOException {
    this.seenFacetDims.clear();
    this.facetFieldsByIndex.clear();
    this.ssdvFieldsByIndex.clear();
    this.assocFieldsByIndex.clear();
    this.assocTypeByField.clear();
    this.assocTypeByField.putAll(config.assocDimTypes);

    for (IndexableField field : doc) {
      if (field.fieldType() == FacetField.TYPE) {
        FacetField facetField = (FacetField) field;
        this.lastDimConfig = config.getDimConfig(facetField.dim);
        if (this.lastDimConfig.multiValued == false) {
          checkDuplicateDim(facetField.dim);
        }
        this.facetFieldsByIndex
            .computeIfAbsent(this.lastDimConfig.indexFieldName, k -> new ArrayList<>())
            .add(facetField);
      }

      if (field.fieldType() == SortedSetDocValuesFacetField.TYPE) {
        SortedSetDocValuesFacetField facetField = (SortedSetDocValuesFacetField) field;
        this.lastDimConfig = config.getDimConfig(facetField.dim);
        if (this.lastDimConfig.multiValued == false) {
          checkDuplicateDim(facetField.dim);
        }
        this.ssdvFieldsByIndex
            .computeIfAbsent(this.lastDimConfig.indexFieldName, k -> new ArrayList<>())
            .add(facetField);
      }

      if (field.fieldType() == AssociationFacetField.TYPE) {
        AssociationFacetField facetField = (AssociationFacetField) field;
        this.lastDimConfig = config.getDimConfig(facetField.dim);
        if (this.lastDimConfig.multiValued == false) {
          checkDuplicateDim(facetField.dim);
        }
        if (this.lastDimConfig.hierarchical) {
          throw new IllegalArgumentException(
              "AssociationFacetField cannot be hierarchical (dim=\"" + facetField.dim + "\")");
        }
        if (this.lastDimConfig.requireDimCount) {
          throw new IllegalArgumentException(
              "AssociationFacetField cannot requireDimCount (dim=\"" + facetField.dim + "\")");
        }
        String indexFieldName = this.lastDimConfig.indexFieldName;
        this.assocFieldsByIndex
            .computeIfAbsent(indexFieldName, k -> new ArrayList<>())
            .add(facetField);
        rememberAssocType(indexFieldName, detectAssocType(facetField));
      }
    }

    config.assocDimTypes.clear();
    config.assocDimTypes.putAll(this.assocTypeByField);

    Document result = new Document();
    processFacetFields(config, taxoWriter, result);
    processSSDVFacetFields(config, result);
    processAssocFacetFields(config, taxoWriter, result);

    for (IndexableField field : doc.getFields()) {
      IndexableFieldType ft = field.fieldType();
      if (ft != FacetField.TYPE
          && ft != SortedSetDocValuesFacetField.TYPE
          && ft != AssociationFacetField.TYPE) {
        result.add(field);
      }
    }
    return result;
  }

  void processFacetFields(FacetsConfig config, TaxonomyWriter taxoWriter, Document doc)
      throws IOException {
    this.seenFacetDims.clear();
    for (Map.Entry<String, List<FacetField>> ent : this.facetFieldsByIndex.entrySet()) {
      String indexFieldName = ent.getKey();
      this.ordinalWorkspace.clear();
      for (FacetField facetField : ent.getValue()) {
        this.lastDimConfig = config.getDimConfig(facetField.dim);
        if (facetField.path.length > 1 && this.lastDimConfig.hierarchical == false) {
          throw new IllegalArgumentException(
              "dimension \""
                  + facetField.dim
                  + "\" is not hierarchical yet has "
                  + facetField.path.length
                  + " components");
        }
        FacetLabel facetLabel = new FacetLabel(facetField.dim, facetField.path);
        checkTaxoWriter(taxoWriter);
        int ordinal = taxoWriter.addCategory(facetLabel);
        this.ordinalWorkspace.append(ordinal);
        appendParentOrdinals(taxoWriter, ordinal, this.lastDimConfig);
        indexDrillDownTerms(doc, indexFieldName, this.lastDimConfig, facetLabel);
      }
      encodeOrdinalsIntoDocument(doc, indexFieldName);
    }
  }

  void appendParentOrdinals(
      TaxonomyWriter taxoWriter, int ordinal, FacetsConfig.DimConfig dimConfig) throws IOException {
    this.lastDimConfig = dimConfig;
    if (dimConfig.multiValued && (dimConfig.hierarchical || dimConfig.requireDimCount)) {
      int parent = taxoWriter.getParent(ordinal);
      while (parent > 0) {
        this.ordinalWorkspace.append(parent);
        parent = taxoWriter.getParent(parent);
      }
      if (dimConfig.requireDimCount == false) {
        this.ordinalWorkspace.setLength(this.ordinalWorkspace.length() - 1);
      }
    }
  }

  void encodeOrdinalsIntoDocument(Document doc, String indexFieldName) {
    this.lastAddedDim = indexFieldName;
    IntsRef ords = this.ordinalWorkspace.get();
    Arrays.sort(ords.ints, ords.offset, ords.offset + ords.length);
    int prev = -1;
    for (int i = 0; i < ords.length; i++) {
      int ord = ords.ints[ords.offset + i];
      if (ord > prev) {
        doc.add(new SortedNumericDocValuesField(indexFieldName, ord));
        prev = ord;
      }
    }
  }

  void processSSDVFacetFields(FacetsConfig config, Document doc) {
    this.seenFacetDims.clear();
    for (Map.Entry<String, List<SortedSetDocValuesFacetField>> ent :
        this.ssdvFieldsByIndex.entrySet()) {
      String indexFieldName = ent.getKey();
      for (SortedSetDocValuesFacetField facetField : ent.getValue()) {
        FacetLabel facetLabel = new FacetLabel(facetField.dim, facetField.path);
        this.lastDimConfig = config.getDimConfig(facetField.dim);
        if (this.lastDimConfig.hierarchical) {
          indexHierarchicalPaths(doc, indexFieldName, facetLabel);
        } else {
          if (facetLabel.length != 2) {
            throw new IllegalArgumentException(
                "dimension \""
                    + facetField.dim
                    + "\" is not hierarchical yet has "
                    + facetField.path.length
                    + " components");
          }
          if (this.lastDimConfig.multiValued && this.lastDimConfig.requireDimCount) {
            doc.add(new SortedSetDocValuesField(indexFieldName, new BytesRef(facetField.dim)));
          }
          String fullPath = encodePath(facetLabel.components, facetLabel.length);
          doc.add(new SortedSetDocValuesField(indexFieldName, new BytesRef(fullPath)));
        }
        indexDrillDownTerms(doc, indexFieldName, this.lastDimConfig, facetLabel);
      }
    }
  }

  void indexHierarchicalPaths(Document doc, String indexFieldName, FacetLabel facetLabel) {
    this.lastAddedDim = indexFieldName;
    for (int i = 0; i < facetLabel.length; i++) {
      String fullPath = encodePath(facetLabel.components, i + 1);
      doc.add(new SortedSetDocValuesField(indexFieldName, new BytesRef(fullPath)));
    }
  }

  void processAssocFacetFields(FacetsConfig config, TaxonomyWriter taxoWriter, Document doc)
      throws IOException {
    this.seenFacetDims.clear();
    for (Map.Entry<String, List<AssociationFacetField>> ent : this.assocFieldsByIndex.entrySet()) {
      this.assocBytes = new byte[16];
      this.assocBytesUpto = 0;
      String indexFieldName = ent.getKey();
      for (AssociationFacetField field : ent.getValue()) {
        checkTaxoWriter(taxoWriter);
        FacetLabel facetLabel = new FacetLabel(field.dim, field.path);
        int ordinal = taxoWriter.addCategory(facetLabel);
        if (this.assocBytesUpto + 4 > this.assocBytes.length) {
          this.assocBytes = ArrayUtil.grow(this.assocBytes, this.assocBytesUpto + 4);
        }
        BitUtil.VH_BE_INT.set(this.assocBytes, this.assocBytesUpto, ordinal);
        this.assocBytesUpto += 4;
        if (this.assocBytesUpto + field.assoc.length > this.assocBytes.length) {
          this.assocBytes =
              ArrayUtil.grow(this.assocBytes, this.assocBytesUpto + field.assoc.length);
        }
        System.arraycopy(
            field.assoc.bytes,
            field.assoc.offset,
            this.assocBytes,
            this.assocBytesUpto,
            field.assoc.length);
        this.assocBytesUpto += field.assoc.length;
        this.lastDimConfig = config.getDimConfig(field.dim);
        indexDrillDownTerms(doc, indexFieldName, this.lastDimConfig, facetLabel);
      }
      doc.add(
          new BinaryDocValuesField(
              indexFieldName, new BytesRef(this.assocBytes, 0, this.assocBytesUpto)));
    }
  }

  void indexDrillDownTerms(
      Document doc, String indexFieldName, FacetsConfig.DimConfig dimConfig, FacetLabel facetLabel) {
    this.lastDimConfig = dimConfig;
    if (dimConfig.drillDownTermsIndexing == FacetsConfig.DrillDownTermsIndexing.NONE) {
      return;
    }
    doc.add(
        new StringField(
            indexFieldName,
            encodePath(facetLabel.components, facetLabel.length),
            Field.Store.NO));
    switch (dimConfig.drillDownTermsIndexing) {
      case NONE:
      case FULL_PATH_ONLY:
        break;
      case DIMENSION_AND_FULL_PATH:
        doc.add(
            new StringField(
                indexFieldName, encodePath(facetLabel.components, 1), Field.Store.NO));
        break;
      case ALL_PATHS_NO_DIM:
        for (int i = 2; i < facetLabel.length; i++) {
          doc.add(
              new StringField(
                  indexFieldName, encodePath(facetLabel.components, i), Field.Store.NO));
        }
        break;
      case ALL:
        for (int i = 1; i < facetLabel.length; i++) {
          doc.add(
              new StringField(
                  indexFieldName, encodePath(facetLabel.components, i), Field.Store.NO));
        }
        break;
      default:
        throw new AssertionError(
            "Drill down term indexing option "
                + dimConfig.drillDownTermsIndexing
                + " is not supported.");
    }
  }

  void addPathConstraint(DrillDownQuery query, String dim, String... path) {
    this.lastAddedDim = dim;
    this.pathComponentCount = path == null ? 0 : path.length;
    String indexedField = query.config.getDimConfig(dim).indexFieldName;
    addDimensionConstraint(query, dim, new TermQuery(DrillDownQuery.term(indexedField, dim, path)));
  }

  void addDimensionConstraint(DrillDownQuery query, String dim, Query subQuery) {
    this.lastAddedDim = dim;
    this.lastSubQuery = subQuery;
    this.assembledClauseCount = query.dimQueries.size();
    if (dimensionIndex(query, dim) < 0) {
      query.drillDownDims.put(dim, query.drillDownDims.size());
      BooleanQuery.Builder builder = new BooleanQuery.Builder();
      query.dimQueries.add(builder);
      query.builtDimQueries.add(null);
    }
    this.dimConstraintIndex = query.drillDownDims.get(dim);
    query.dimQueries.get(this.dimConstraintIndex).add(subQuery, Occur.SHOULD);
    query.dirtyDimQueryIndex.add(this.dimConstraintIndex);
  }

  BooleanQuery assembleDrillDownQuery(DrillDownQuery query) {
    this.drillQueryBuilder = new BooleanQuery.Builder();
    this.assembledClauseCount = 0;
    this.lastAssembledQuery = query.baseQuery;
    if (query.baseQuery != null) {
      this.drillQueryBuilder.add(query.baseQuery, Occur.MUST);
      this.assembledClauseCount++;
    }
    for (Query dimQuery : rebuildDirtyDimQueries(query)) {
      this.drillQueryBuilder.add(dimQuery, Occur.FILTER);
      this.assembledClauseCount++;
      this.lastAssembledQuery = dimQuery;
    }
    return this.drillQueryBuilder.build();
  }

  Query[] rebuildDirtyDimQueries(DrillDownQuery query) {
    this.assembledClauseCount = query.dirtyDimQueryIndex.size();
    for (Integer dirtyDimIndex : query.dirtyDimQueryIndex) {
      this.dimConstraintIndex = dirtyDimIndex;
      query.builtDimQueries.set(dirtyDimIndex, query.dimQueries.get(dirtyDimIndex).build());
    }
    query.dirtyDimQueryIndex.clear();
    this.lastAssembledQuery =
        query.builtDimQueries.isEmpty() ? null : query.builtDimQueries.get(0);
    return query.builtDimQueries.toArray(new Query[0]);
  }

  int dimensionIndex(DrillDownQuery query, String dim) {
    this.lastAddedDim = dim;
    Integer index = query.drillDownDims.get(dim);
    this.dimConstraintIndex = index == null ? -1 : index;
    return this.dimConstraintIndex;
  }

  void collectFacetHit(FacetsCollector fc, int doc) throws IOException {
    this.hitCounter = fc.totalHits;
    this.currentScorer = fc.scorer;
    this.keepCollectedScores = fc.keepScores;
    fc.docsBuilder.grow(1).add(doc);
    if (this.keepCollectedScores) {
      if (this.hitCounter >= fc.scores.length) {
        float[] newScores = new float[ArrayUtil.oversize(this.hitCounter + 1, 4)];
        System.arraycopy(fc.scores, 0, newScores, 0, this.hitCounter);
        fc.scores = newScores;
      }
      fc.scores[this.hitCounter] = this.currentScorer.score();
    }
